\label{th:1}
Assume that the function $f$ is twice differentiable with a Hessian matrix
$\nabla^2f$ satisfying $m\bfI_p\preceq \nabla^2f(\bx)\preceq M\bfI_p$ for every
$\bx\in\RR^p$.
Let $\mu_1,\mu_2$ and $\mu_2'$ be three probability measures on $\RR^p$. Let
us define the product measures $\mu = \mu_1\otimes\mu_2$ and
$\mu' = \mu_1\otimes\mu_2'$. For every $\gamma,t>0$, there exist numbers
$\alpha\le \sqrt{2}/\gamma$ and $\beta\ge \{m\wedge (\gamma^2-M) \}/\gamma$
such that
\begin{align}\label{exp1}
W_2(\mu\bfP_t^{\bL},\mu'\bfP_t^{\bL})
	&\le \alpha
	e^{-\beta\,t}
	W_2(\mu,\mu').
\end{align}
More precisely, for every $v\in [0,\gamma/2[$, we have\footnote{One can observe that \eqref{exp1} can be deduced from
\eqref{exp2} by taking $v=0$.}
\begin{align}\label{exp2}
W_2(\mu\bfP_t^{\bL},\mu'\bfP_t^{\bL})
	&\le \frac{\sqrt{2((\gamma-v)^2+v^2)}}{\gamma-2v}
	\exp\bigg\{\frac{(v^2- m)\vee(M-(\gamma-v)^2)}{\gamma-2v}\,t\bigg\}
	W_2(\mu,\mu').
\end{align}

\label{prop:1}
Let $\bV_0,\bL_0$ and $\bL_0'$ be random vectors in $\mathbb{R}^{p}$. Let $(\bV_t,\bL_t)$
and $(\bV'_t,\bL'_t)$ be kinetic Langevin diffusions driven by the same Brownian motion
and starting from $(\bV_0,\bL_0)$ and $(\bV_0,\bL'_0)$, respectively. Let $v$ be an
arbitrary real number from $[0,\gamma/2)$. We have
\begin{align}
\|\bL_t-\bL'_t\|_2
	&\le \frac{\sqrt{2((\gamma-v)^2+v^2)}}{\gamma-2v}
	\exp\bigg\{\frac{(v^2-m)\vee(M-(\gamma-v)^2)}{\gamma-2v}\,t\bigg\}
	\|\bL_0-\bL'_0\|_2,\quad \forall t\ge 0.
\end{align}

As a consequence, we can see that for $\gamma^2\ge 2(M+m)$ by setting
$$
v = \frac{\gamma-\sqrt{\gamma^2-4m}}{2}\ge \frac{m}{\gamma}.
$$
we arrive at
\begin{equation}
\|\bL_t-\bL'_t\|_2
	\le  \bigg(\frac{2\gamma^2-4m}{\gamma^2-4m}\bigg)^{1/2}
	e^{-v t}\,\|\bL_0-\bL'_0\|_2,\qquad \forall t\ge 0.
\end{equation}

\label{prop:4}
  Assume that, for some constants $m,M,M_2>0$, the function $f$ is
$m$-strongly convex, its gradient is $M$-Lipschitz, and its Hessian is $M_2$-Lipschitz for the spectral norm. If the parameter $\gamma$ and the step size $h$ of the kinetic Langevin diffusion satisfy the inequalities
$$
\gamma^2\ge m+M,\qquad h\le\frac{1}{5\gamma\varkappa}\wedge \frac{m}{4\sqrt{5p}\,M_2}.
$$
  Then
  \begin{align}
      \left\|\bfP^{-1}\begin{bmatrix}
     {\bV}_{kh} - \Tilde\bV_{kh} \\
      {\bL}_{kh} - \Tilde\bL_{kh}
\end{bmatrix}\right\|_{{\LL}_2}
\le&
\left(1-\frac{mh}{4\gamma}\right)^k
\left\|\bfP^{-1}\begin{bmatrix}
     \bV_0-\Tilde{\bV}_0  \\
      \bL_0-\Tilde{\bL}_0
\end{bmatrix}\right\|_{{\LL}_2}
\\
&+\frac{4\sqrt{2}\,(M-m)}{m}\,\gamma h e^{-\frac{m^2}{160 M_2^2h^2}}
+\gamma h^2\left(\frac{M_2}{m}\sqrt{p^2+2p}+\frac{M^{3/2}}{m}\sqrt{p}\right).
  \end{align}
